def calcular_cuota_referencial(monto: float, plazo_meses: int, tea_anual_pct: float = 28.5, desgravamen_mensual_pct: float = 0.075) -> float:
    if monto <= 0 or plazo_meses <= 0:
        return 0.0
    tea_decimal = tea_anual_pct / 100.0
    tem = ((1.0 + tea_decimal) ** (1.0 / 12.0)) - 1.0
    if tem > 0:
        factor = (tem * ((1.0 + tem) ** plazo_meses)) / (((1.0 + tem) ** plazo_meses) - 1.0)
        cuota_capital_interes = monto * factor
    else:
        cuota_capital_interes = monto / plazo_meses
    seguro_desgravamen_promedio = monto * (desgravamen_mensual_pct / 100.0) * 0.55
    return round(cuota_capital_interes + seguro_desgravamen_promedio, 2)

# ----------------- CRIPTOGRAFÍA, HASHING Y DEFENSA ACTIVA -----------------

PBKDF2_ITERATIONS = 200_000
SESSION_EXPIRATION_HOURS = 2
_rate_limit_lock = threading.Lock()
_login_lock = threading.Lock()

def hash_password(password: str) -> str:
    salt = secrets.token_bytes(16)
    key = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, PBKDF2_ITERATIONS)
    return f"pbkdf2_sha256${PBKDF2_ITERATIONS}${salt.hex()}${key.hex()}"

def verify_password(plain_password: str, stored_hash: str) -> bool:
    if not plain_password or not stored_hash:
        return False
    if stored_hash.startswith("pbkdf2_sha256$"):
        try:
            parts = stored_hash.split("$")
            if len(parts) != 4:
                return False
            iterations = int(parts[1])
            salt = bytes.fromhex(parts[2])
            expected_key = bytes.fromhex(parts[3])
            computed_key = hashlib.pbkdf2_hmac("sha256", plain_password.encode("utf-8"), salt, iterations)
            return hmac.compare_digest(computed_key, expected_key)
        except Exception:
            return False
    return hmac.compare_digest(plain_password.strip(), stored_hash.strip())

def is_hash_pbkdf2(hash_str: str) -> bool:
    return bool(hash_str and hash_str.startswith("pbkdf2_sha256$"))

def generate_secure_token() -> str:
    return secrets.token_urlsafe(32)

def hash_token(token: str) -> str:
    return hashlib.sha256(token.encode("utf-8")).hexdigest()

def sanitize_csv_cell(value: Any) -> str:
    if value is None:
        return ""
    text = str(value).replace("\x00", "").strip()
    if text and text[0] in ("=", "+", "-", "@", "\t", "\r"):
        return f"'{text}"
    return text

_CONTROL_CHARS = re.compile(r"[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]")
_SCRIPT_TAGS = re.compile(r"<\s*script[^>]*>.*?<\s*/\s*script\s*>", re.IGNORECASE | re.DOTALL)

def sanitize_input_text(text: Optional[str], max_length: int = 500) -> str:
    if not text:
        return ""
    clean = _SCRIPT_TAGS.sub("", str(text))
    clean = _CONTROL_CHARS.sub("", clean).strip()
    return clean[:max_length]

class InMemoryRateLimiter:
    def __init__(self):
        self._requests = defaultdict(list)
        self._last_clean = time.time()

    def check_limit(self, key: str, max_requests: int, window_seconds: int) -> Tuple[bool, int]:
        now = time.time()
        with _rate_limit_lock:
            if now - self._last_clean > 180:
                cutoff = now - 3600
                to_del = [k for k, ts in self._requests.items() if not [t for t in ts if t > cutoff]]
                for k in to_del:
                    del self._requests[k]
                self._last_clean = now

            timestamps = self._requests[key]
            cutoff = now - window_seconds
            valid_ts = [t for t in timestamps if t > cutoff]
            self._requests[key] = valid_ts

            if len(valid_ts) >= max_requests:
                oldest = valid_ts[0]
                retry_after = max(1, int(oldest + window_seconds - now))
                return False, retry_after

            valid_ts.append(now)
            return True, 0

class LoginBruteForceProtector:
    MAX_ATTEMPTS = 5
    LOCKOUT_SECONDS = 900  # 15 minutos

    def __init__(self):
        self._failures = defaultdict(list)
        self._lockouts = {}

    def is_locked(self, ip: str) -> Tuple[bool, int]:
        now = time.time()
        with _login_lock:
            if ip in self._lockouts:
                until = self._lockouts[ip]
                if now < until:
                    return True, int(until - now)
                del self._lockouts[ip]
                self._failures[ip] = []
            return False, 0

    def record_failure(self, ip: str) -> Tuple[int, int]:
        now = time.time()
        with _login_lock:
            cutoff = now - self.LOCKOUT_SECONDS
            self._failures[ip] = [t for t in self._failures[ip] if t > cutoff]
            self._failures[ip].append(now)
            if len(self._failures[ip]) >= self.MAX_ATTEMPTS:
                self._lockouts[ip] = now + self.LOCKOUT_SECONDS
                return len(self._failures[ip]), self.LOCKOUT_SECONDS
            return len(self._failures[ip]), 0

    def record_success(self, ip: str):
        with _login_lock:
            self._failures.pop(ip, None)
            self._lockouts.pop(ip, None)

solicitud_limiter = InMemoryRateLimiter()
general_api_limiter = InMemoryRateLimiter()
login_protector = LoginBruteForceProtector()

