# ----------------- BASE DE DATOS SQLITE SEGURA -----------------

DB_PATH = os.path.join(os.path.dirname(__file__), "crediavanza.db")

def get_connection():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode = WAL;")
    conn.execute("PRAGMA foreign_keys = ON;")
    conn.execute("PRAGMA busy_timeout = 5000;")
    return conn

def init_db():
    conn = get_connection()
    cursor = conn.cursor()
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS solicitudes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        codigo TEXT UNIQUE NOT NULL,
        monto REAL NOT NULL,
        plazo INTEGER NOT NULL,
        finalidad TEXT NOT NULL,
        cuota_estimada REAL NOT NULL,
        nombres TEXT NOT NULL,
        apellidos TEXT NOT NULL,
        tipo_documento TEXT NOT NULL,
        numero_documento TEXT NOT NULL,
        fecha_nacimiento TEXT NOT NULL,
        telefono TEXT NOT NULL,
        whatsapp TEXT NOT NULL,
        email TEXT NOT NULL,
        departamento TEXT NOT NULL,
        provincia TEXT NOT NULL,
        distrito TEXT NOT NULL,
        direccion TEXT NOT NULL,
        situacion_laboral TEXT NOT NULL,
        ingresos_mensuales REAL NOT NULL,
        acepta_politica INTEGER NOT NULL DEFAULT 1,
        autoriza_contacto INTEGER NOT NULL DEFAULT 1,
        estado TEXT NOT NULL DEFAULT 'PENDIENTE',
        notas_asesor TEXT DEFAULT '',
        ip_cliente TEXT DEFAULT '',
        creado_en TEXT NOT NULL,
        actualizado_en TEXT NOT NULL
    )
    """)
    cursor.execute("CREATE INDEX IF NOT EXISTS idx_solicitudes_codigo ON solicitudes(codigo);")
    cursor.execute("CREATE INDEX IF NOT EXISTS idx_solicitudes_doc ON solicitudes(numero_documento);")
    cursor.execute("CREATE INDEX IF NOT EXISTS idx_solicitudes_estado ON solicitudes(estado);")

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS configuraciones (
        clave TEXT PRIMARY KEY,
        valor TEXT NOT NULL,
        descripcion TEXT
    )
    """)

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS sesiones_admin (
        token_hash TEXT PRIMARY KEY,
        rol TEXT NOT NULL DEFAULT 'asesor',
        ip_creacion TEXT,
        user_agent TEXT,
        creado_en TEXT NOT NULL,
        expira_en TEXT NOT NULL,
        ultimo_acceso TEXT NOT NULL
    )
    """)

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS auditoria_seguridad (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        fecha TEXT NOT NULL,
        evento TEXT NOT NULL,
        ip TEXT,
        usuario_rol TEXT,
        detalles TEXT,
        severidad TEXT NOT NULL DEFAULT 'INFO'
    )
    """)
    cursor.execute("CREATE INDEX IF NOT EXISTS idx_auditoria_fecha ON auditoria_seguridad(fecha);")

    default_admin_hash = hash_password("crediavanza2026")
    default_asesor_hash = hash_password("asesor2026")

    defaults = [
        ("tea_referencial", "28.50", "TEA"),
        ("tasa_seguro_desgravamen", "0.075", "Seguro Desgravamen"),
        ("razon_social", "Credi Avanza Servicios Financieros S.A.C.", "Razón Social"),
        ("ruc", "20609205572", "RUC"),
        ("direccion_fiscal", "Av. Víctor Andrés Belaúnde 147, San Isidro, Lima - Perú", "Dirección"),
        ("telefono_atencion", "+51 1 700 8920", "Teléfono"),
        ("whatsapp_atencion", "+51 987 654 321", "WhatsApp"),
        ("email_contacto", "contacto@crediavanza.pe", "Email"),
        ("horario_atencion", "Lunes a Viernes 8:30 a.m. - 6:30 p.m. | Sábados 9:00 a.m. - 1:00 p.m.", "Horario"),
        ("admin_pin", default_admin_hash, "PIN Admin PBKDF2"),
        ("asesor_pin", default_asesor_hash, "PIN Asesor PBKDF2"),
    ]
    for c, v, d in defaults:
        cursor.execute("INSERT OR IGNORE INTO configuraciones (clave, valor, descripcion) VALUES (?, ?, ?)", (c, v, d))

    # Auto-migrar claves en texto plano si existieran
    cursor.execute("SELECT clave, valor FROM configuraciones WHERE clave IN ('admin_pin', 'asesor_pin')")
    for row in cursor.fetchall():
        clave, val = row["clave"], row["valor"]
        if not is_hash_pbkdf2(val):
            cursor.execute("UPDATE configuraciones SET valor = ? WHERE clave = ?", (hash_password(val), clave))

    conn.commit()
    conn.close()

def registrar_auditoria(evento: str, ip: str = "", usuario_rol: str = "", detalles: str = "", severidad: str = "INFO"):
    try:
        now_str = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        conn = get_connection()
        c = conn.cursor()
        c.execute("""
        INSERT INTO auditoria_seguridad (fecha, evento, ip, usuario_rol, detalles, severidad)
        VALUES (?, ?, ?, ?, ?, ?)
        """, (now_str, evento, ip, usuario_rol, sanitize_input_text(detalles, 400), severidad))
        conn.commit()
        conn.close()
    except Exception:
        pass

def get_all_config():
    conn = get_connection()
    c = conn.cursor()
    c.execute("SELECT clave, valor FROM configuraciones WHERE clave NOT LIKE '%pin%' AND clave NOT LIKE '%secret%'")
    rows = c.fetchall()
    conn.close()
    return {row["clave"]: row["valor"] for row in rows}

def get_config_val(clave: str):
    conn = get_connection()
    c = conn.cursor()
    c.execute("SELECT valor FROM configuraciones WHERE clave = ?", (clave,))
    row = c.fetchone()
    conn.close()
    return row["valor"] if row else None

def update_config(clave, valor):
    conn = get_connection()
    c = conn.cursor()
    c.execute("""
    INSERT INTO configuraciones (clave, valor)
    VALUES (?, ?)
    ON CONFLICT(clave) DO UPDATE SET valor = excluded.valor
    """, (clave, valor))
    conn.commit()
    conn.close()

def crear_sesion_db(rol: str, ip: str, user_agent: str) -> str:
    raw_token = generate_secure_token()
    token_h = hash_token(raw_token)
    now = datetime.now()
    expira = now + timedelta(hours=SESSION_EXPIRATION_HOURS)
    conn = get_connection()
    c = conn.cursor()
    c.execute("""
    INSERT INTO sesiones_admin (token_hash, rol, ip_creacion, user_agent, creado_en, expira_en, ultimo_acceso)
    VALUES (?, ?, ?, ?, ?, ?, ?)
    """, (
        token_h, rol, ip, user_agent[:250],
        now.strftime("%Y-%m-%d %H:%M:%S"),
        expira.strftime("%Y-%m-%d %H:%M:%S"),
        now.strftime("%Y-%m-%d %H:%M:%S")
    ))
    conn.commit()
    conn.close()
    return raw_token

def obtener_sesion_db(raw_token: str) -> Optional[Dict[str, Any]]:
    if not raw_token:
        return None
    token_h = hash_token(raw_token)
    now_str = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    conn = get_connection()
    c = conn.cursor()
    c.execute("SELECT * FROM sesiones_admin WHERE token_hash = ?", (token_h,))
    row = c.fetchone()
    if not row:
        conn.close()
        return None
    if row["expira_en"] < now_str:
        c.execute("DELETE FROM sesiones_admin WHERE token_hash = ?", (token_h,))
        conn.commit()
        conn.close()
        return None
    c.execute("UPDATE sesiones_admin SET ultimo_acceso = ? WHERE token_hash = ?", (now_str, token_h))
    conn.commit()
    conn.close()
    return dict(row)

def cerrar_sesion_db(raw_token: str):
    if not raw_token:
        return
    token_h = hash_token(raw_token)
    conn = get_connection()
    c = conn.cursor()
    c.execute("DELETE FROM sesiones_admin WHERE token_hash = ?", (token_h,))
    conn.commit()
    conn.close()

# ----------------- MIDDLEWARE DE CABECERAS DE SEGURIDAD -----------------

class SecurityHeadersMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        response: Response = await call_next(request)
        response.headers["X-Content-Type-Options"] = "nosniff"
        response.headers["X-Frame-Options"] = "DENY"
        response.headers["Strict-Transport-Security"] = "max-age=31536000; includeSubDomains; preload"
        response.headers["Referrer-Policy"] = "strict-origin-when-cross-origin"
        response.headers["Permissions-Policy"] = "geolocation=(), microphone=(), camera=(), payment=()"
        response.headers["X-XSS-Protection"] = "1; mode=block"
        response.headers["Content-Security-Policy"] = (
            "default-src 'self'; "
            "script-src 'self' 'unsafe-inline' https://www.gstatic.com https://fonts.googleapis.com https://cdn.tailwindcss.com; "
            "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; "
            "font-src 'self' https://fonts.gstatic.com; "
            "img-src 'self' data: https:; "
            "connect-src 'self'; "
            "frame-ancestors 'none'; "
            "base-uri 'self'; "
            "form-action 'self';"
        )
        response.headers["Server"] = "Protected-Gateway"
        return response

