# Manejador global de excepciones para evitar fugas de stack trace
@app.exception_handler(Exception)
async def global_exception_handler(request: Request, exc: Exception):
    incident_id = str(uuid.uuid4())[:8]
    client_ip = get_client_ip(request)
    registrar_auditoria("ERROR_INTERNO", ip=client_ip, detalles=f"Incidente: {incident_id} | {type(exc).__name__}: {str(exc)}", severidad="ERROR")
    return JSONResponse(
        status_code=500,
        content={
            "status": "error",
            "mensaje": "Ocurrió un error inesperado al procesar la solicitud. Nuestro equipo de seguridad ha sido notificado.",
            "incidente": incident_id
        }
    )

def get_client_ip(request: Request) -> str:
    forwarded = request.headers.get("x-forwarded-for")
    if forwarded:
        return forwarded.split(",")[0].strip()
    return request.client.host if request.client else "127.0.0.1"

# Inyección de dependencia de autenticación RBAC
async def get_current_session(request: Request) -> Dict[str, Any]:
    token = None
    auth_header = request.headers.get("Authorization")
    if auth_header and auth_header.startswith("Bearer "):
        token = auth_header[7:].strip()
    if not token:
        token = request.cookies.get("credi_session")
    if not token:
        token = request.query_params.get("token")

    if not token:
        raise HTTPException(status_code=401, detail="Autenticación requerida. Sesión no proporcionada.")

    sesion = obtener_sesion_db(token)
    if not sesion:
        raise HTTPException(status_code=401, detail="Sesión inválida o expirada. Por favor vuelva a iniciar sesión.")
    return sesion

async def require_admin(session: Dict[str, Any] = Depends(get_current_session)) -> Dict[str, Any]:
    if session.get("rol") != "admin":
        raise HTTPException(status_code=403, detail="Acceso denegado: Se requiere rol de Administrador para esta operación.")
    return session

