@app.post("/api/simular")
def api_simular(datos: SimulacionRequest):
    cfg = get_all_config()
    tea = float(cfg.get("tea_referencial", 28.50))
    desgravamen = float(cfg.get("tasa_seguro_desgravamen", 0.075))
    cuota = calcular_cuota_referencial(datos.monto, datos.plazo, tea, desgravamen)
    return {
        "monto": datos.monto,
        "plazo": datos.plazo,
        "cuota_mensual_estimada": cuota,
        "tea_aplicada": tea,
        "seguro_desgravamen_mensual": desgravamen
    }

@app.post("/api/solicitar", status_code=status.HTTP_201_CREATED)
async def api_solicitar(solicitud: SolicitudPrestamoCreate, request: Request):
    client_ip = get_client_ip(request)

    # 1. Rate limiting: máx 5 solicitudes por 10 min por IP
    allowed, retry_after = solicitud_limiter.check_limit(client_ip, max_requests=5, window_seconds=600)
    if not allowed:
        registrar_auditoria("RATE_LIMIT_SOLICITUD", ip=client_ip, detalles="Exceso de solicitudes de préstamo", severidad="WARN")
        raise HTTPException(
            status_code=429,
            detail=f"Has superado el límite de solicitudes permitidas. Por favor intenta en {retry_after} segundos.",
            headers={"Retry-After": str(retry_after)}
        )

    # 2. Verificación Honeypot anti-bots
    if solicitud.website_antispam:
        registrar_auditoria("HONEYPOT_ACTIVADO", ip=client_ip, detalles="Bot detectado mediante trampa honeypot", severidad="WARN")
        raise HTTPException(status_code=400, detail="Acceso denegado por políticas de seguridad.")

    cfg = get_all_config()
    tea = float(cfg.get("tea_referencial", 28.50))
    desgravamen = float(cfg.get("tasa_seguro_desgravamen", 0.075))
    cuota = calcular_cuota_referencial(solicitud.monto, solicitud.plazo, tea, desgravamen)
    
    year = datetime.now().year
    codigo = f"CA-{year}-{random.randint(100000, 999999)}"
    now_iso = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    conn = get_connection()
    cursor = conn.cursor()
    cursor.execute("""
    INSERT INTO solicitudes (
        codigo, monto, plazo, finalidad, cuota_estimada,
        nombres, apellidos, tipo_documento, numero_documento,
        fecha_nacimiento, telefono, whatsapp, email,
        departamento, provincia, distrito, direccion,
        situacion_laboral, ingresos_mensuales,
        acepta_politica, autoriza_contacto,
        estado, notas_asesor, ip_cliente,
        creado_en, actualizado_en
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'PENDIENTE', '', ?, ?, ?)
    """, (
        codigo, solicitud.monto, solicitud.plazo, solicitud.finalidad, cuota,
        solicitud.nombres, solicitud.apellidos, solicitud.tipo_documento, solicitud.numero_documento,
        solicitud.fecha_nacimiento, solicitud.telefono, solicitud.whatsapp, solicitud.email,
        solicitud.departamento, solicitud.provincia, solicitud.distrito, solicitud.direccion,
        solicitud.situacion_laboral, solicitud.ingresos_mensuales,
        1 if solicitud.acepta_politica else 0, 1 if solicitud.autoriza_contacto else 0,
        client_ip, now_iso, now_iso
    ))
    conn.commit()
    conn.close()

    # Registro de auditoría (enmascarando documento por Ley 29733)
    doc_masked = solicitud.numero_documento[:2] + "****" + solicitud.numero_documento[-2:]
    registrar_auditoria("SOLICITUD_CREADA", ip=client_ip, detalles=f"Código: {codigo} | Monto: S/ {solicitud.monto} | Doc: {doc_masked}", severidad="INFO")

    return {
        "status": "success",
        "codigo": codigo,
        "monto": solicitud.monto,
        "plazo": solicitud.plazo,
        "cuota_estimada": cuota,
        "mensaje": "¡Tu solicitud ha sido enviada correctamente y protegida bajo la Ley N.º 29733!"
    }

# ----------------- RUTAS DE ADMINISTRACIÓN Y ASESORES (BLINDADAS) -----------------

@app.post("/api/admin/login")
async def api_admin_login(cred: LoginAdminRequest, request: Request, response: Response):
    client_ip = get_client_ip(request)
    user_agent = request.headers.get("user-agent", "")

    # 1. Comprobar bloqueo por fuerza bruta
    is_locked, remaining = login_protector.is_locked(client_ip)
    if is_locked:
        registrar_auditoria("BLOQUEO_BRUTE_FORCE", ip=client_ip, detalles=f"Intento en IP bloqueada. Restan {remaining}s", severidad="CRITICAL")
        raise HTTPException(
            status_code=429,
            detail=f"IP bloqueada temporalmente por exceso de intentos fallidos. Intente de nuevo en {int(remaining/60)} minutos.",
            headers={"Retry-After": str(remaining)}
        )

    # 2. Verificar credenciales con PBKDF2
    admin_hash = get_config_val("admin_pin")
    asesor_hash = get_config_val("asesor_pin")

    rol_autenticado = None
    if admin_hash and verify_password(cred.pin, admin_hash):
        rol_autenticado = "admin"
        if not is_hash_pbkdf2(admin_hash):
            update_config("admin_pin", hash_password(cred.pin))
    elif asesor_hash and verify_password(cred.pin, asesor_hash):
        rol_autenticado = "asesor"
        if not is_hash_pbkdf2(asesor_hash):
            update_config("asesor_pin", hash_password(cred.pin))

    if not rol_autenticado:
        attempts, lockout = login_protector.record_failure(client_ip)
        registrar_auditoria("LOGIN_FALLIDO", ip=client_ip, detalles=f"Intento fallido ({attempts}/5)", severidad="WARN")
        if lockout > 0:
            raise HTTPException(
                status_code=429,
                detail=f"Has alcanzado el límite de intentos. Acceso bloqueado por 15 minutos por seguridad.",
                headers={"Retry-After": str(lockout)}
            )
        raise HTTPException(status_code=401, detail="Clave de acceso incorrecta.")

    # 3. Login exitoso
    login_protector.record_success(client_ip)
    token = crear_sesion_db(rol_autenticado, client_ip, user_agent)
    registrar_auditoria("LOGIN_EXITOSO", ip=client_ip, usuario_rol=rol_autenticado, detalles="Sesión iniciada correctamente", severidad="INFO")

    # Configurar cookie HttpOnly SameSite=Lax
    response.set_cookie(
        key="credi_session",
        value=token,
        httponly=True,
        samesite="lax",
        secure=False,  # Starlette lo activará en conexiones TLS
        max_age=SESSION_EXPIRATION_HOURS * 3600
    )

    return {"status": "ok", "token": token, "rol": rol_autenticado}

@app.post("/api/admin/logout")
async def api_admin_logout(request: Request, response: Response):
    auth_header = request.headers.get("Authorization")
    token = None
    if auth_header and auth_header.startswith("Bearer "):
        token = auth_header[7:].strip()
    if not token:
        token = request.cookies.get("credi_session")

    if token:
        cerrar_sesion_db(token)
    response.delete_cookie("credi_session")
    registrar_auditoria("LOGOUT", ip=get_client_ip(request), detalles="Sesión cerrada", severidad="INFO")
    return {"status": "ok"}

