@app.patch("/api/admin/solicitudes/{codigo}/estado")
async def api_admin_estado(
    codigo: str,
    payload: ActualizarEstadoRequest,
    request: Request,
    session: Dict[str, Any] = Depends(get_current_session)
):
    estados_validos = ["PENDIENTE", "EN_EVALUACION", "APROBADO", "OBSERVADO", "RECHAZADO", "CONTACTADO"]
    nuevo_estado = payload.estado.strip().upper()
    if nuevo_estado not in estados_validos:
        raise HTTPException(status_code=400, detail="Estado no permitido.")

    notas_clean = sanitize_input_text(payload.notas_asesor, 1000)
    now_iso = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    conn = get_connection()
    c = conn.cursor()
    c.execute("UPDATE solicitudes SET estado = ?, notas_asesor = ?, actualizado_en = ? WHERE codigo = ?", (nuevo_estado, notas_clean, now_iso, codigo))
    if c.rowcount == 0:
        conn.close()
        raise HTTPException(status_code=404, detail="Solicitud no encontrada.")
    conn.commit()
    conn.close()

    registrar_auditoria("CAMBIO_ESTADO", ip=get_client_ip(request), usuario_rol=session["rol"], detalles=f"Solicitud {codigo} cambiada a {nuevo_estado}", severidad="INFO")
    return {"status": "ok"}

@app.get("/api/admin/solicitudes/export")
async def api_admin_export(
    request: Request,
    session: Dict[str, Any] = Depends(require_admin)  # Solo Administradores pueden exportar masivamente
):
    conn = get_connection()
    c = conn.cursor()
    c.execute("SELECT * FROM solicitudes ORDER BY id DESC")
    rows = c.fetchall()
    conn.close()

    out = io.StringIO()
    out.write("\ufeff")  # BOM UTF-8
    writer = csv.writer(out, delimiter=";")
    writer.writerow([
        "Código", "Fecha Creación", "Estado", "Monto Solicitado (S/)", "Plazo (meses)",
        "Cuota Estimada (S/)", "Nombres", "Apellidos", "Tipo Documento", "Número Documento",
        "Teléfono", "WhatsApp", "Email", "Distrito", "Provincia", "Departamento", "Situación Laboral", "Ingresos Mensuales"
    ])
    
    # Sanitizar rigurosamente cada celda contra CSV Injection (CWE-1236)
    for r in rows:
        writer.writerow([
            sanitize_csv_cell(r["codigo"]),
            sanitize_csv_cell(r["creado_en"]),
            sanitize_csv_cell(r["estado"]),
            sanitize_csv_cell(r["monto"]),
            sanitize_csv_cell(r["plazo"]),
            sanitize_csv_cell(r["cuota_estimada"]),
            sanitize_csv_cell(r["nombres"]),
            sanitize_csv_cell(r["apellidos"]),
            sanitize_csv_cell(r["tipo_documento"]),
            sanitize_csv_cell(r["numero_documento"]),
            sanitize_csv_cell(r["telefono"]),
            sanitize_csv_cell(r["whatsapp"]),
            sanitize_csv_cell(r["email"]),
            sanitize_csv_cell(r["distrito"]),
            sanitize_csv_cell(r["provincia"]),
            sanitize_csv_cell(r["departamento"]),
            sanitize_csv_cell(r["situacion_laboral"]),
            sanitize_csv_cell(r["ingresos_mensuales"]),
        ])

    registrar_auditoria("EXPORT_CSV", ip=get_client_ip(request), usuario_rol=session["rol"], detalles=f"Exportación de {len(rows)} registros", severidad="WARN")
    out.seek(0)
    return StreamingResponse(
        iter([out.getvalue()]),
        media_type="text/csv; charset=utf-8",
        headers={"Content-Disposition": f"attachment; filename=solicitudes_crediavanza_{datetime.now().strftime('%Y%m%d')}.csv"}
    )

@app.post("/api/admin/configuracion")
async def api_admin_config(
    datos: ActualizarConfiguracionRequest,
    request: Request,
    session: Dict[str, Any] = Depends(require_admin)  # Solo Administradores pueden cambiar datos de empresa
):
    campos = {
        "tea_referencial": datos.tea_referencial,
        "telefono_atencion": datos.telefono_atencion,
        "whatsapp_atencion": datos.whatsapp_atencion,
        "email_contacto": datos.email_contacto,
        "horario_atencion": datos.horario_atencion,
        "razon_social": datos.razon_social,
        "ruc": datos.ruc,
        "direccion_fiscal": datos.direccion_fiscal
    }

    conn = get_connection()
    c = conn.cursor()
    for clave, valor in campos.items():
        if valor is not None and str(valor).strip():
            clean_val = sanitize_input_text(str(valor).strip(), 250)
            c.execute("""
            INSERT INTO configuraciones (clave, valor)
            VALUES (?, ?)
            ON CONFLICT(clave) DO UPDATE SET valor = excluded.valor
            """, (clave, clean_val))

    # Cambio opcional de clave con PBKDF2
    if datos.admin_pin and len(datos.admin_pin.strip()) >= 6:
        nuevo_hash = hash_password(datos.admin_pin.strip())
        c.execute("""
        INSERT INTO configuraciones (clave, valor)
        VALUES ('admin_pin', ?)
        ON CONFLICT(clave) DO UPDATE SET valor = excluded.valor
        """, (nuevo_hash,))

    conn.commit()
    conn.close()

    registrar_auditoria("CAMBIO_CONFIG", ip=get_client_ip(request), usuario_rol=session["rol"], detalles="Actualización de datos empresariales/financieros", severidad="WARN")
    return {"status": "ok", "mensaje": "Configuración actualizada y protegida exitosamente."}

